 function walk(node,path){const counts=new Map();for(const child of node.children){let next=path;const label=child.dataset.inspectorGroup||child.dataset.inspectorItem;if(label){const n=counts.get(label)||0;counts.set(label,n+1);next=path.concat([[label,n]]);}if(child.tagName==='DETAILS')entries.push([JSON.stringify(next),child]);walk(child,next);}}
