 const viewport=$('preview-viewport'),frame=$('preview'),wrap=$('frame-wrap'),style=getComputedStyle(viewport),availableW=Math.max(1,viewport.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight)),availableH=Math.max(1,viewport.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom));
 const chosen=Number($('device').value),width=fullView?window.innerWidth:chosen===1280?Math.max(1025,window.innerWidth):chosen,height=fullView?window.innerHeight:chosen===1280?window.innerHeight:chosen===768?1024:chosen===320?740:844;
 previewScale=Math.min(1,availableW/width,availableH/height);frame.style.width=width+'px';frame.style.height=height+'px';frame.style.transform='scale('+previewScale+')';wrap.style.width=(width*previewScale)+'px';wrap.style.height=(height*previewScale)+'px';$('zoom-label').textContent=width+' × '+height+' · '+Math.round(previewScale*100)+'%';$('device').options[0].textContent='Desktop · '+width;
