async function captureWorkspace(){await startup;flushInputs();synchronize();const document=M.clone(baseData);const strip=v=>{if(!v||typeof v!=='object')return;delete v.publishing;Object.values(v).forEach(strip);};strip(document);const entries=[...assets];if(entries.reduce((n,[p,b])=>n+b.size,0)>15*1024*1024)throw Error('Shared sessions support up to 15 MB of assets. Export a ZIP for larger portfolios.');const files=[];for(const [path,blob]of entries){const bytes=new Uint8Array(await blob.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=32768)text+=String.fromCharCode(...bytes.subarray(i,i+32768));files.push({path,content:btoa(text)});}return {document,assets:files,folders:[...folders]};}
async function applySharedWorkspace(snapshot,{preservePublishing=false}={}){await startup;const document=M.clone(snapshot.document);for(const device of ['desktop','tablet','mobile']){const errors=M.validate(L.resolve(document,device));if(errors.length)throw Error(errors[0]);}const nextAssets=new Map();let total=0;for(const file of snapshot.assets){if(!/^assets\//.test(file.path)||file.path.split('/').some(p=>p==='..'||p==='.')||file.path.includes('\\'))throw Error('Invalid shared asset path.');const raw=atob(file.content),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));total+=bytes.length;if(total>15*1024*1024)throw Error('Shared assets exceed 15 MB.');nextAssets.set(file.path,new Blob([bytes],{type:mimeFor(file.path)}));}if(preservePublishing&&baseData.site.publishing)document.site.publishing=M.clone(baseData.site.publishing);applyingShared=true;try{clearTimeout(saveTimer);pendingInputs.clear();setDocument(document);assets=nextAssets;folders=new Set(snapshot.folders);data.sections.forEach(protectedFolders);ensureArchive();history=[];future=[];if(selection.section&&!section())selection={};if(selection.cell&&!cell())selection={section:selection.section};render();queueSave();}finally{applyingShared=false;}}
function setSharedAccess(role){sharedReadOnly=role==='viewer'||role==='connecting';document.body.dataset.shareRole=role||'';if(sharedReadOnly){mode='browse';isolation=null;closeModal();selection={};}else if(mode==='browse'&&role==='editor')mode='edit';render();}
// Add generated content as one undoable transaction. Existing documents and publishing metadata stay intact.
async function applyDesign(raw,media=new Map(),name='Design from image'){
 await startup;if(sharedReadOnly)throw Error('This is a view-only canvas.');
 flushInputs();synchronize();const plan=CraftDesign.normalize(raw),title=String(name).trim().slice(0,70)||'Design from image';
 let id=uniqueId(title),suffix=2;
 const occupied=new Set(['desktop','tablet','mobile'].flatMap(device=>L.resolve(baseData,device).sections.map(s=>s.id)));
 while([...occupied].some(old=>old===id||old.startsWith(id+'-')))id=uniqueId(title)+'-'+suffix++;
 const preliminary=CraftDesign.compile(plan,M,{name:title,id}),assetSection=preliminary.sections[0].id,paths={},staged=new Map();let total=0;
 for(const r of plan.regions.filter(r=>r.enabled&&['image','background'].includes(r.type))){
  const blob=media.get(r.id);if(!blob||typeof blob.arrayBuffer!=='function'||!['image/webp','image/png'].includes(blob.type))throw Error('An image crop is missing. Refresh the preview and try again.');
  total+=blob.size;if(total>30*1024*1024)throw Error('Generated image assets exceed 30 MB. Use a smaller reference image.');
  const path='assets/'+assetSection+'/images/'+r.id+(blob.type==='image/webp'?'.webp':'.png');if(assets.has(path))throw Error('An asset with this name already exists. Choose a different section name.');paths[r.id]=path;staged.set(path,blob);
 }
 const result=CraftDesign.compile(plan,M,{name:title,id,assets:paths}),next=M.clone(baseData);next.sections.push(...result.sections);
 for(const device of ['tablet','mobile']){const resolved=L.resolve(baseData,device);resolved.sections.push(...result[device]);next.deviceOverrides[device]=L.diff(L.resolve(next),resolved);}
 for(const device of ['desktop','tablet','mobile']){const errors=M.validate(L.resolve(next,device));if(errors.length)throw Error(errors[0]);}
 if(sharedReadOnly)throw Error('This canvas is now view-only.');
 const applied=commit(()=>{scope='desktop';baseData=next;data=L.resolve(next);$('device').value='1280';mode='edit';isolation=null;previewPage='';selection={section:result.sections[0].id};for(const s of result.sections)protectedFolders(s);for(const [path,blob]of staged)assets.set(path,blob);});
 if(!applied)throw Error('The generated layout could not be applied. Your previous portfolio was restored.');
 notify('Added '+result.sections.length+' editable section'+(result.sections.length===1?'':'s')+'. Undo reverses the import.');return {sectionIds:result.sections.map(s=>s.id),assetCount:staged.size};
}
