window.CraftCareer=window.PortfolioForge={ready:startup,captureWorkspace,applySharedWorkspace,setSharedAccess,applyDesign,canEdit:()=>!sharedReadOnly,flushPending:flushInputs,getDocument:()=>M.clone(baseData),getResolvedDocument:()=>M.clone(data),buildZip,importWebsite,preflight,validate:validateDocument,setPublishing:value=>{flushInputs();synchronize();baseData.site.publishing=M.clone(value);data.site.publishing=M.clone(value);queueSave();}};
